public class PackageArchitectureDemo {
    public static void main(String[] args) {
        // Package names represent structured business capabilities
        String domain = "learnbyself.com";
        String feature = "catalog";

        String fullPackage = buildPackageName(domain, feature);
        System.out.println("Domain: " + domain);
        System.out.println("Constructed Package: " + fullPackage);
    }

    public static String buildPackageName(String domain, String feature) {
        String[] parts = domain.split("\\.");
        StringBuilder sb = new StringBuilder();
        for (int i = parts.length - 1; i >= 0; i--) {
            sb.append(parts[i].toLowerCase()).append(".");
        }
        sb.append(feature.toLowerCase());
        return sb.toString();
    }
}

