import java.util.*;

public class CycleDetector {
    public static boolean hasDirectCycle(Map<String, List<String>> deps, String pkgA, String pkgB) {
        if (deps == null || pkgA == null || pkgB == null) return false;
        List<String> depsA = deps.getOrDefault(pkgA, Collections.emptyList());
        List<String> depsB = deps.getOrDefault(pkgB, Collections.emptyList());
        return depsA.contains(pkgB) && depsB.contains(pkgA);
    }

    public static void main(String[] args) {
        Map<String, List<String>> graph = new HashMap<>();
        graph.put("com.app.user", Arrays.asList("com.app.order"));
        graph.put("com.app.order", Arrays.asList("com.app.user"));
        System.out.println("Cycle detected: " + hasDirectCycle(graph, "com.app.user", "com.app.order"));
    }
}

