public class LayerRuleCheck {
    public static boolean isDependencyAllowed(String caller, String target) {
        if (caller == null || target == null) return false;
        String c = caller.toLowerCase();
        String t = target.toLowerCase();
        if (c.equals("controller")) return t.equals("service") || t.equals("model");
        if (c.equals("service")) return t.equals("repository") || t.equals("model");
        if (c.equals("repository")) return t.equals("model");
        return false;
    }

    public static void main(String[] args) {
        System.out.println(isDependencyAllowed("controller", "service"));
        System.out.println(isDependencyAllowed("repository", "controller"));
    }
}

