import java.util.*;

public class PackageReport {
    public static Map<String, Integer> countClassesByPackage(List<String> classFQNs) {
        Map<String, Integer> counts = new TreeMap<>();
        if (classFQNs == null) return counts;
        for (String fqn : classFQNs) {
            int lastDot = fqn.lastIndexOf('.');
            String pkg = (lastDot == -1) ? "default" : fqn.substring(0, lastDot);
            counts.put(pkg, counts.getOrDefault(pkg, 0) + 1);
        }
        return counts;
    }

    public static void main(String[] args) {
        List<String> list = Arrays.asList(
            "com.bank.user.User",
            "com.bank.user.UserService",
            "com.bank.order.Order"
        );
        System.out.println(countClassesByPackage(list));
    }
}

