public class SealingValidator {
    public static boolean isLegalAccess(String classPackage, boolean isPublic, String callerPackage) {
        if (isPublic) return true;
        if (classPackage == null || callerPackage == null) return false;
        return classPackage.equals(callerPackage);
    }

    public static void main(String[] args) {
        System.out.println(isLegalAccess("com.bank.core", false, "com.bank.core"));
        System.out.println(isLegalAccess("com.bank.core", false, "com.bank.web"));
    }
}
